import React from 'react';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { WidgetDataGuard } from '../components/WidgetDataGuard';
import type { WidgetProps } from '../types';
import { resolveLabel } from '../utils/resolveChartFields';
import { useChartData } from '../hooks/useChartData';
import { DEFAULT_CHART_COLORS } from '../utils/chartColors';

const ChartBarHorizontal: React.FC<WidgetProps> = ({ definition, period, preference }) => {
  const { chartData, valueKeys, categoryField, aliases, data, loading, error } =
    useChartData(definition, preference, period);

  return (
    <WidgetDataGuard loading={loading} error={error} data={data}>
      <div className="w-full h-full p-4">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={chartData} layout="vertical" margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
            <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#E2E8F0" />
            <XAxis type="number" hide />
            <YAxis dataKey={categoryField} type="category" axisLine={false} tickLine={false} tick={{ fill: '#4A5568', fontSize: 13, fontWeight: 500 }} />
            <Tooltip cursor={{ fill: '#F7FAFC' }} contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }} />
            {valueKeys.length > 1 && <Legend wrapperStyle={{ paddingTop: '10px' }} />}
            {valueKeys.map((key, i) => (
              <Bar key={key} dataKey={key} name={resolveLabel(key, aliases)} fill={DEFAULT_CHART_COLORS[i % DEFAULT_CHART_COLORS.length]} radius={[0, 4, 4, 0]} barSize={20} />
            ))}
          </BarChart>
        </ResponsiveContainer>
      </div>
    </WidgetDataGuard>
  );
};

export default ChartBarHorizontal;
